window.ox.install(({action})=>{action('readCarResults',{async invoke({pickupDate,returnDate,limit=40}){const q=new URL(location.href).searchParams;if(q.get('date1')!==pickupDate||q.get('date2')!==returnDate)throw Error('Rental search dates do not match');const norm=v=>String(v||'').replace(/\s+/g,' ').trim();const cards=()=>[...new Set([...document.querySelectorAll('#offer-cards-list ol.results-list > li.offer-card-desktop')].filter(e=>e.querySelector('button[aria-label^="Reserve Item, "]')).concat(Array.from(document.querySelectorAll('span.is-visually-hidden')).filter(e=>e.textContent.startsWith('Reserve Item, ')).map(e=>e.closest('.uitk-card')).filter(Boolean)))];const deadline=Date.now()+22000;while(Date.now()<deadline&&!cards().length){if(document.title==='Bot or Not?'||document.body.innerText.includes('Show us your human side'))throw Error('Expedia requires human verification');await new Promise(r=>setTimeout(r,200));}if(!cards().length)throw Error('Expedia rental results unavailable');for(let i=0;i<3&&cards().length<limit;i++){const b=Array.from(document.querySelectorAll('button')).find(e=>e.innerText.trim()==='Show more');if(!b)break;const before=cards().length;b.click();const end=Date.now()+8000;while(Date.now()<end&&cards().length===before)await new Promise(r=>setTimeout(r,200));if(cards().length===before)break;}return {context:norm(document.querySelector('h1')?.innerText)+' | '+q.get('time1')+' → '+q.get('time2'),items:cards().slice(0,limit).map(c=>({summary:norm(c.innerText),detailsUrl:c.querySelector('a[href*="/carsearch/details"]')?.href||''})),nextCursor:null,coverage:'partial: loaded public offers, not exhaustive'};}});});